  // when they share BOTH the same level+XP AND the same name once a
  // known type-suffix ("ore", "rocks", "logs", "tree", "vein", ...) is
  // stripped from the end. A same-level+XP match alone isn't enough —
  // lots of unrelated items coincidentally cost the same XP (e.g.
  // several different Crafting capes/hats all cost exactly 2.5 XP), and
  // merging on that alone would have deleted real, distinct entries.
